const fs = require('node:fs');
const client = require('./client.cjs');
const packet = JSON.parse(fs.readFileSync(0, 'utf8'));
// Review04: preserve the server result before client code can mutate it.
const originalPacket = JSON.parse(JSON.stringify(packet));
function error(call) { try { call(); } catch (e) { return e.name; } return 'no_error'; }
const result=packet.map(client.total);
function canonical(value) {
    if (Array.isArray(value)) return value.map(canonical);
    if (value !== null && typeof value === 'object') return Object.fromEntries(Object.keys(value).sort().map(k => [k,canonical(value[k])]));
    return value;
}
console.log(JSON.stringify(canonical([originalPacket,result])));

